package com.ateliercampus.controller;
import com.ateliercampus.dao.*;import com.ateliercampus.model.*;import com.ateliercampus.service.*;import com.ateliercampus.web.SecuriteFilter;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;import java.time.*;import java.util.*;
@WebServlet(urlPatterns={"/catalogue","/atelier","/connexion","/deconnexion","/mes-inscriptions","/inscription/action","/gestion/*"})
public class AtelierCampusServlet extends HttpServlet {
 private final AtelierService ateliers=new AtelierService();private final InscriptionService inscriptions=new InscriptionService();private final AuthentificationService auth=new AuthentificationService();
 private void view(HttpServletRequest r,HttpServletResponse p,String v)throws ServletException,IOException{r.setAttribute("csrf",SecuriteFilter.token(r.getSession()));r.getRequestDispatcher("/WEB-INF/vues/"+v+".jsp").forward(r,p);}private void msg(HttpServletRequest r,String m){r.setAttribute("message",m);}private long id(String x){return Long.parseLong(x);}
 protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{String path=r.getServletPath(),info=r.getPathInfo();try{switch(path){case "/catalogue"->{List<Atelier> list=ateliers.list(r.getParameter("q"));Map<Long,Integer> counts=new HashMap<>();for(Atelier a:list)counts.put(a.getId(),ateliers.confirmed(a.getId()));r.setAttribute("ateliers",list);r.setAttribute("confirmes",counts);view(r,p,"catalogue");}case "/atelier"->{Atelier a=ateliers.find(id(r.getParameter("id")));if(a==null){p.sendError(404,"Atelier introuvable.");return;}r.setAttribute("atelier",a);r.setAttribute("confirmes",ateliers.confirmed(a.getId()));r.setAttribute("commence",!a.getDateHeure().isAfter(LocalDateTime.now()));view(r,p,"detail");}case "/connexion"->view(r,p,"connexion");case "/deconnexion"->p.sendError(405);case "/mes-inscriptions"->{r.setAttribute("inscriptions",inscriptions.pourEtudiant((Long)r.getSession().getAttribute("utilisateur")));view(r,p,"mes-inscriptions");}case "/gestion"->{if(info==null||"/".equals(info)||"/ateliers".equals(info)){r.setAttribute("ateliers",ateliers.list(""));view(r,p,"gestion");}else if("/nouveau".equals(info)){view(r,p,"atelier-form");}else if("/modifier".equals(info)){Atelier a=ateliers.find(id(r.getParameter("id")));if(a==null){p.sendError(404);return;}r.setAttribute("atelier",a);r.setAttribute("dateHeureInput",a.getDateHeure().toString());view(r,p,"atelier-form");}else if("/participants".equals(info)){long aid=id(r.getParameter("id"));r.setAttribute("atelier",ateliers.find(aid));r.setAttribute("participants",inscriptions.participants(aid));view(r,p,"participants");}else p.sendError(404);}default->p.sendError(404);}}catch(IllegalArgumentException e){p.sendError(400,e.getMessage());}catch(Exception e){throw new ServletException("Une erreur est survenue pendant le traitement.",e);}}
 protected void doPost(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{r.setCharacterEncoding("UTF-8");String path=r.getServletPath(),info=r.getPathInfo();try{switch(path){case "/connexion"->{Etudiant e=auth.connecter(r.getParameter("email"),r.getParameter("mot_de_passe"));if(e==null){msg(r,"Adresse électronique ou mot de passe invalide.");view(r,p,"connexion");return;}HttpSession old=r.getSession();old.invalidate();HttpSession s=r.getSession(true);s.setMaxInactiveInterval(1800);s.setAttribute("utilisateur",e.getId());s.setAttribute("nom",e.getNom());s.setAttribute("role",e.getRole());p.sendRedirect(r.getContextPath()+("GESTIONNAIRE".equals(e.getRole())?"/gestion/ateliers":"/mes-inscriptions"));}case "/deconnexion"->{HttpSession s=r.getSession(false);if(s!=null)s.invalidate();p.sendRedirect(r.getContextPath()+"/catalogue");}case "/inscription/action"->{long user=(Long)r.getSession().getAttribute("utilisateur");if("annuler".equals(r.getParameter("action")))inscriptions.annuler(user,id(r.getParameter("id")));else inscriptions.inscrire(user,id(r.getParameter("atelierId")));p.sendRedirect(r.getContextPath()+"/mes-inscriptions?ok="+("annuler".equals(r.getParameter("action"))?"annulation":"inscription"));}case "/gestion"->{if("/supprimer".equals(info)){ateliers.delete(id(r.getParameter("id")));}else{Atelier a=new Atelier();String aid=r.getParameter("id");if(aid!=null&&!aid.isBlank())a.setId(id(aid));a.setTitre(required(r,"titre").trim());a.setDescription(required(r,"description").trim());a.setDateHeure(LocalDateTime.parse(required(r,"dateHeure")));a.setCapacite(Integer.parseInt(required(r,"capacite")));ateliers.save(a);}p.sendRedirect(r.getContextPath()+"/gestion/ateliers?ok=sauvegarde");}default->p.sendError(405);}}catch(IllegalArgumentException e){p.sendError(400,e.getMessage());}catch(Exception e){if(e.getMessage()!=null&&(e.getMessage().contains("refus")||e.getMessage().contains("capacité"))){p.sendError(409,e.getMessage());}else throw new ServletException("Opération impossible.",e);}}
 private String required(HttpServletRequest r,String k){String v=r.getParameter(k);if(v==null||v.isBlank())throw new IllegalArgumentException("Le champ "+k+" est obligatoire.");return v;}
}

